def transform(grid):
    """Extend rays from each interior mark; paired boundary runs copy its lane."""
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]
    h, w = len(src), len(src[0])
    counts = {v: sum(row.count(v) for row in src) for v in {x for row in src for x in row}}
    bg = max(counts, key=counts.get)

    def runs(side):
        line = src[0] if side == 'top' else src[-1] if side == 'bottom' else [src[r][0 if side == 'left' else w-1] for r in range(h)]
        ans=[]; i=0
        while i<len(line):
            if line[i]==bg: i+=1; continue
            color,j=line[i],i+1
            while j<len(line) and line[j]==color: j+=1
            ans.append((side,color,i,j)); i=j
        return ans

    for sa,sb in (('left','right'),('top','bottom')):
        for a in runs(sa):
            for b in runs(sb):
                if a[1]!=b[1] or a[3]-a[2]!=b[3]-b[2]: continue
                vertical=sa=='left'
                for own,mate in ((a,b),(b,a)):
                    for off in range(own[3]-own[2]):
                        lane=own[2]+off; paired=mate[2]+off
                        cells=[(lane,c) for c in range(1,w-1)] if vertical else [(r,lane) for r in range(1,h-1)]
                        dr,dc=((0,-1) if own[0]=='left' else (0,1)) if vertical else ((-1,0) if own[0]=='top' else (1,0))
                        for r,c in cells:
                            color=src[r][c]
                            if color in (bg,own[1]): continue
                            out[r][c]=4
                            rr,cc=r+dr,c+dc
                            while 0<rr<h-1 and 0<cc<w-1 and src[rr][cc]==bg:
                                out[rr][cc]=color
                                rr+=dr; cc+=dc
                            if vertical:
                                for x in range(1,w-1):
                                    if src[paired][x]==bg: out[paired][x]=color
                            else:
                                for x in range(1,h-1):
                                    if src[x][paired]==bg: out[x][paired]=color
    # Paired lanes can include cells on the interior rows/columns adjacent to edges.
    for r in range(h):
        for c in range(w):
            if out[r][c] == bg and src[r][c] == bg:
                pass
    return out

